package kr.workbench;
import burp.api.montoya.*;import burp.api.montoya.http.message.*;import burp.api.montoya.http.message.requests.*;import javax.swing.*;import java.util.*;import java.util.List;import java.util.concurrent.atomic.*;import java.nio.file.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;
/** Native Burp account/task journey on the owned ephemeral lab, no API adapters. */
public final class RuntimeAssessmentAudit {
 static final List<Map<String,Object>> checks=new ArrayList<>();static final String base="http://127.0.0.1:18299";
 static void check(String name,boolean ok,Object detail){checks.add(Map.of("name",name,"passed",ok,"detail",Objects.toString(detail)));if(!ok)throw new AssertionError(name);}
 static void edt(Runnable r)throws Exception{SwingUtilities.invokeAndWait(r);}
 static void flush(ActivityPanel p)throws Exception{var latch=new java.util.concurrent.CountDownLatch(1);p.submit(latch::countDown);if(!latch.await(15,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("account queue timeout");edt(p::refresh);}
 static void idle(AuthComparePanel p)throws Exception{for(int i=0;i<800;i++){edt(()->{});if(p.active.get()==0)return;Thread.sleep(25);}throw new AssertionError("auth timeout");}
 public static void run(MontoyaApi api,Path out)throws Exception{ActivityPanel activity=null;AuthComparePanel auth=null;BountySupportPanel support=null;try{
  WorkbenchScope.install(api).add(base+"/",true);RuntimeUserAudit.api=api;var alice=RuntimeUserAudit.accounts.get("alice");var bob=RuntimeUserAudit.accounts.get("bob");var admin=RuntimeUserAudit.accounts.get("admin");HttpRequest owner=RuntimeUserAudit.req("/api/community/fixed/posts/102",bob);var original=RuntimeUserAudit.send(owner);check("native account baseline private object",original.response().statusCode()==200,"owned Bob private post");
  AtomicReference<ActivityPanel> panel=new AtomicReference<>();AtomicReference<AuthComparePanel> compared=new AtomicReference<>();AtomicReference<BountySupportPanel> supported=new AtomicReference<>();edt(()->{var p=new ActivityPanel(api);panel.set(p);var a=new AuthComparePanel(api,()->List.of(original));compared.set(a);a.trackingSource=p.tracker.assessments::accounts;a.trackingCreate=p.tracker.assessments::register;a.trackingBind=p.tracker.assessments::bind;a.trackingSink=p::accountInspection;supported.set(new BountySupportPanel(api,()->List.of(original),a,p));});activity=panel.get();auth=compared.get();support=supported.get();var p=activity;var a=auth;var s=support;var t=p.tracker.assessments;
  String aliceId=t.register(new AssessmentTracker.AccountInput("Alice",base,"USER","A",false)),adminId=t.register(new AssessmentTracker.AccountInput("Admin",base,"ADMIN","A",false)),bobId=t.register(new AssessmentTracker.AccountInput("Bob",base,"USER","B",false));
  edt(()->{var users=List.of(alice,admin,bob);var ids=List.of(aliceId,adminId,bobId);for(int i=0;i<users.size();i++){var user=users.get(i);a.observe(RuntimeUserAudit.req("/api/auth/me",user),original.response());a.assign(i,a.credentials.values().stream().filter(c->user.cookie().equals(c.headers().get("cookie"))).findFirst().orElseThrow());a.profileNames[i].setText(user.name());a.profileOwners[i].setText(user.id());a.trackingAccounts[i]=ids.get(i);}a.sessionSettingsContent();for(int i=0;i<3;i++){a.trackingChoices[i].setSelectedIndex(0);for(int j=1;j<a.trackingChoices[i].getItemCount();j++)if(a.trackingChoices[i].getItemAt(j).id().equals(ids.get(i))){a.trackingChoices[i].setSelectedIndex(j);break;}}check("native account selector retains stable identity",Arrays.equals(a.trackingAccounts,new String[]{aliceId,adminId,bobId}),"production combo actions");a.cookieNames=Set.of("JSESSIONID");a.matrixRules.setText("GET /api/community/fixed/posts/102 DENY ALLOW ALLOW");a.compareSelection();});idle(a);flush(p);
  check("native Alice denied and Admin allowed",a.runs.get(0).packets[0].response.statusCode()==404&&a.runs.get(0).packets[1].response.statusCode()==200,"native HTTP 404 / 200");check("native original credential not mistaken for cross-account validation",a.runs.get(0).packets[2].note.contains("동일 인증"),a.runs.get(0).packets[2].note);check("native inspection counters are account-specific",List.of(aliceId,adminId,bobId).stream().allMatch(id->t.view(id,"GET",owner.url(),List.of()).inspections()==1),"three stable account ids");check("native inspection does not auto-complete",List.of(aliceId,adminId,bobId).stream().noneMatch(id->t.view(id,"GET",owner.url(),List.of()).state().equals("점검 완료")),"manual completion still required");
  t.complete(aliceId,"GET",owner.url(),p.tracker.parameterNames("GET",owner.url()),true);check("native Alice completion isolated from Bob",t.view(aliceId,"GET",owner.url(),List.of()).state().equals("점검 완료")&&!t.view(bobId,"GET",owner.url(),List.of()).state().equals("점검 완료"),"independent account states");
  String task=t.createTask("게시글 권한 점검","세 계정으로 같은 private 게시글 확인",Set.of(aliceId,adminId,bobId),true);t.addTarget(task,"GET",owner.url());check("native work has three required account/API pairs",t.taskOperations(task).size()==3,t.tasks().get(0).state());t.complete(adminId,"GET",owner.url(),List.of(),true);t.complete(bobId,"GET",owner.url(),List.of(),true);check("native task waits for evidence ZIP",t.tasks().get(0).state().equals("증거 저장 필요"),t.tasks().get(0).state());
  edt(()->{a.history.setRowSelectionInterval(0,0);s.captureAuth();});check("native evidence captures all stable account ids",s.evidence.stream().filter(e->!e.account().isEmpty()).map(BountyEvidence.Item::account).distinct().count()==3,s.evidence.size());check("native capture is not saved evidence",t.tasks().get(0).evidence()==0,"prepared only");Path evidence=out.resolve("account-task-evidence.zip");s.writeEvidence(evidence,"게시글 계정 점검","owned training lab","Alice denial / Admin allowance / Bob baseline",List.copyOf(s.evidence),Set.copyOf(s.evidenceHeaders),Set.copyOf(s.evidenceSecrets),false,p.tracker.save(),null,List.of());flush(p);check("native successful evidence write updates task",t.tasks().get(0).state().equals("완료 준비")&&t.tasks().get(0).evidence()==1,t.tasks().get(0).state());t.completeTask(task,true);check("native work completion is explicit",t.tasks().get(0).state().equals("업무 완료"),t.tasks().get(0).state());
  try(ZipFile z=new ZipFile(evidence.toFile())){String data=new String(z.getInputStream(z.getEntry("evidence.json")).readAllBytes(),StandardCharsets.UTF_8);check("native ZIP account provenance with secret redaction",data.contains(aliceId)&&data.contains(adminId)&&data.contains(bobId)&&!data.contains(alice.cookie())&&!data.contains(bob.cookie()),"ids retained; cookies redacted");}
  var changed=RuntimeUserAudit.req("/api/community/fixed/posts/102?view=detail",alice);p.tracker.observe(changed,"REPEATER");check("native new input reopens only completed account operation",t.view(aliceId,"GET",owner.url(),List.of()).state().equals("재검토 필요"),t.view(aliceId,"GET",owner.url(),List.of()).review());check("native completed work reopens on changed account coverage",t.tasks().get(0).state().equals("재검토 필요"),t.tasks().get(0).state());t.complete(aliceId,"GET",owner.url(),p.tracker.parameterNames("GET",owner.url()),true);t.complete(adminId,"GET",owner.url(),p.tracker.parameterNames("GET",owner.url()),true);t.complete(bobId,"GET",owner.url(),p.tracker.parameterNames("GET",owner.url()),true);t.completeTask(task,true);
  String saved=p.tracker.save();ActivityTracker restored=new ActivityTracker();restored.load(saved);check("native account/work metadata roundtrip",restored.assessments.accounts().size()==3&&restored.assessments.tasks().get(0).state().equals("업무 완료"),"version 3 persistence");check("native persisted metadata excludes sessions and bindings",!saved.contains(alice.cookie())&&!saved.contains(admin.cookie())&&!saved.contains(alice.csrf())&&restored.assessments.match(owner).isEmpty(),"sessions require explicit rebind");MetadataExport.xlsx(out.resolve("account-work-coverage.xlsx"),p.tracker.workbook());check("native account/work Excel export",Files.size(out.resolve("account-work-coverage.xlsx"))>1000,"account and work sheets");edt(()->{p.refresh();p.assessmentPanel.selectAccount(aliceId);check("native account and work UI controllers populated",p.assessmentPanel.accountTable.getRowCount()>0&&p.assessmentPanel.taskTable.getRowCount()==1,"actual production Swing views");});
 edt(()->{a.clearSlot(1);a.clearSlot(2);a.refreshEnabled[0].setSelected(true);a.refreshUrls[0].setText(base+"/api/auth/me");a.refreshTokenPaths[0].setText("$.MISSING_TOKEN");a.compareSelection();});idle(a);flush(p);check("native missing refresh token reopens account",t.view(aliceId,"GET",owner.url(),List.of()).review().contains("갱신 실패"),"refresh returned actual HTTP but missing JSON token prevented target replay");check("native failed refresh reopens completed work",t.tasks().get(0).state().equals("재검토 필요"),t.tasks().get(0).state());Files.writeString(out.resolve("account-work-final.json"),p.tracker.save(),StandardCharsets.UTF_8);
 }catch(Throwable ex){checks.add(Map.of("name","account/task audit exception","passed",false,"detail",ex.toString()));}finally{if(support!=null){var s=support;edt(s::close);}if(auth!=null){var a=auth;edt(a::close);}if(activity!=null){var p=activity;edt(p::close);}Files.writeString(out.resolve("account-task-audit.json"),MetadataExport.json(Map.of("extension","0.21.0","burp",api.burpSuite().version().toString(),"checks",checks)),StandardCharsets.UTF_8);}}
}
